function boundary(title,text,footer=''){return `<div class="boundary"><h3>${esc(title)}</h3><p>${esc(text)}</p>${footer}</div>`}
function persistentError(id){if(!model.error&&!/失败|无效|失效/.test(scenario))return '';if(['device-name','selected-backup','transfer-detail','pair-scan'].includes(id))return `<div class="sheet-error" role="alert">${icon('alert')}<strong>${T(id==='pair-scan'?'配对未完成':id==='transfer-detail'?'文件尚未保存到相册':'操作未完成',id==='pair-scan'?'Pairing did not complete':id==='transfer-detail'?'File not saved to gallery':'Operation did not complete')}</strong><small>${T('详情与恢复入口仍在下方。','Details and recovery actions remain below.')}</small></div>`;return ''}
function footer(id){if(id==='photo-preview')return button(L('settings_done'),'close');if(id==='diagnostic-share'){if(model.systemSharing)return button(T('返回准备窗口','Return to preparation'),'share-return');if(busy)return button(L('logs_export_preparing'),'noop','primary',true);return actions(button(L('close'),'close'),['文件已准备','分享取消','返回'].includes(scenario)?button(L('logs_export_share'),'share-report','primary'):button(L('retry_task'),'prepare-report','primary'))}if(['system','reading'].includes(info(id).kind))return button(L('settings_done'),'close');if(id==='pair-scan'){if(scenario==='配对成功')return button(L('settings_done'),'pair-done','primary');if(scenario==='校验中')return button(T('正在校验…','Validating…'),'noop','primary',true);return actions(button(L('cancel'),'close'),scenario==='相机权限被拒绝'?open(L('photos_open_settings'),'system-settings','primary'):scenario==='扫描中'?button(T('模拟扫描有效码','Simulate valid scan'),'pair-validate','primary'):button(L('apple_scan_again'),'scan-again','primary'))}if(id==='selected-backup')return actions(button(L('cancel'),'close'),button(L('backup_selected_confirm_action'),'confirm-backup','primary'));if(id==='device-name')return actions(button(L('device_cancel'),'close'),button(L('device_save'),'save-name','primary',!model.draftName.trim()));if(id==='transfer-detail'&&['发送失败','重试失败','重试中'].includes(scenario))return actions(button(L('close'),'close'),button(L('retry_task'),'retry-detail','primary'));if(id==='activity-log')return actions(open(L('logs_export'),'diagnostic-share'),button(L('settings_done'),'close'));return button(L('settings_done'),'close')}
function remember(){const c=$('.content');if(c)offsets.set(route,c.scrollTop)}
function navigate(id,fromTab=false){remember();if(nav.some(n=>n[0]===id))fromTab=true;if(fromTab){stack=[];tab=id}else if(route!==id){stack.push(route)}route=id;modal=null;modalStack=[];scenario=info(id).states[0];feedback='';model.error='';render()}
function present(id){remember();const kind=info(id).kind;if(kind==='page'||kind==='inline'||kind==='reading'){navigate(id);return}if(modal)modalStack.push({id:modal,scenario});else pageScenario=scenario;modal=id;focusAfterRender='.sheet-head .icon-button';scenario=info(id).states[0];feedback='';model.error='';model.failedOnce=false;if(id==='device-name')model.draftName=model.name;if(id==='selected-backup')model.rebackup=false;if(id==='diagnostic-share'){model.systemSharing=false;render();act('prepare-report');return}render()}
function close(){if(busy)return;const closing=modal;focusAfterRender=closing?'[data-open=\"'+closing+'\"]':'';if(modalStack.length){const old=modalStack.pop();modal=old.id;scenario=old.scenario}else{modal=null;scenario=pageScenario}feedback='';model.error='';render()}
function notify(text){feedback=text;render()}
function simulateSaving(operation){if(busy)return;const failed=/失败/.test(scenario)&&!model.failedOnce;busy=true;feedback=T('正在保存…','Saving…');render();setTimeout(()=>{busy=false;if(failed){model.failedOnce=true;model.error=T('操作未完成，保留原值和输入，请重试。','The operation did not complete. Previous values and input are retained. Retry when ready.');feedback=model.error;render()}else{operation();feedback=T('已保存（原型模拟）','Saved (prototype simulation)');render()}},360)}
function render(){const current=modal||route;const entry=info(current);$('#scenario').innerHTML=entry.states.map(s=>`<option ${s===scenario?'selected':''}>${esc(s)}</option>`).join('');$('#catalog').innerHTML=catalog.filter(c=>(c.title+' '+c.titleEn+' '+c.path).toLowerCase().includes($('#search').value.toLowerCase())).map(c=>`<button data-catalog="${c.id}" class="${c.id===current?'active':''}">${esc(locale==='en'?c.titleEn:c.title)}<small>${esc(c.kind)} · ${esc(c.path)}</small></button>`).join('');$('#contract').innerHTML=`<strong>${esc(entry.path)}</strong><br>${esc(entry.source)} · ${esc(entry.symbol)}<br>${esc(entry.states.join(' / '))}<br>${esc(entry.native)}`;const page=info(route);const activeScenario=scenario;if(modal)scenario=pageScenario;const pageHTML=body(route);scenario=activeScenario;$('#app').innerHTML=`<header class="navigation">${stack.length?'<button class="icon-button" data-action="back" aria-label="'+esc(T('返回','Back'))+'">'+icon('back')+'</button>':''}<div class="library-heading"><h1 data-library-title>${esc(route==='library'&&model.selecting?T(`已选 ${selected.size} 项`,`${selected.size} selected`):screenTitle(page))}</h1>${route==='library'&&!model.selecting?`<small>${T('共 '+demoFiles.filter(f=>model.kind==='all'||f.kind===model.kind).length+' 项',demoFiles.filter(f=>model.kind==='all'||f.kind===model.kind).length+' items')}</small>`:''}</div>${route==='library'?model.selecting?`<div class="library-toolbar selection-tools">${button(L('settings_done'),'library-select','text')}<button class="button primary compact-backup" data-open="selected-backup" ${!selected.size||!model.paired?'disabled':''}>${T('备份','Back up')}</button></div>`:`<div class="library-toolbar">${open(T('类型：','Type: ')+mediaName(model.kind),'library-filter','text')}</div>`:''}</header><main class="content" aria-label="${esc(screenTitle(page))}">${pageHTML}${!modal&&feedback?`<div class="prototype-feedback" role="status">${esc(feedback)}</div>`:''}</main><nav class="tabs" aria-label="${T('主导航','Main navigation')}">${nav.map(([id,key,symbol])=>`<button data-tab="${id}" class="${tab===id?'active':''}" aria-current="${tab===id?'page':'false'}">${icon(symbol)}${esc(L(key))}</button>`).join('')}</nav>`;if(modal){const entering=activeModalID!==modal;activeModalID=modal;$('#app').inert=true;$('#modal-host').innerHTML=`<div class="overlay ${entering?'enter':''} ${entry.kind==='popover'?'popover':entry.kind==='fullscreen'?'native-preview':''}"><section class="sheet ${entering?'enter':''} ${busy?'busy':''}" role="dialog" aria-modal="true" aria-labelledby="sheet-title">${modal==='photo-preview'?`<header class="native-preview-head"><span></span><h2 id="sheet-title">${esc(screenTitle(entry))}</h2><button data-action="close">${esc(L('settings_done'))}</button></header>`:`<header class="sheet-head"><h2 id="sheet-title">${esc(screenTitle(entry))}</h2><button class="icon-button" data-action="close" aria-label="${esc(L('close'))}" ${busy?'disabled':''}>${icon('close')}</button></header>` }${persistentError(modal)}<div class="sheet-body">${body(modal)}${feedback?`<div class="prototype-feedback" role="status">${esc(feedback)}</div>`:''}</div>${modal==='photo-preview'?'':`<footer class="sheet-foot">${footer(modal)}</footer>`}</section></div>`}else{activeModalID='';$('#app').inert=false;$('#modal-host').innerHTML=''}requestAnimationFrame(()=>{const c=$('.content');if(c)c.scrollTop=offsets.get(route)||0;if(focusAfterRender){const focus=$(focusAfterRender);if(focus)focus.focus({preventScroll:true});focusAfterRender=''}});document.documentElement.lang=locale==='en'?'en':'zh-CN'}
function act(action){switch(action){case'library-select':remember();model.selecting=!model.selecting;if(!model.selecting)selected.clear();render();break;case'prepare-report':{const fail=scenario==='导出失败'&&!model.failedOnce;model.failedOnce=true;busy=true;model.systemSharing=false;scenario='进入说明';render();setTimeout(()=>{busy=false;scenario=fail?'导出失败':'文件已准备';render()},360);break}case'share-report':model.systemSharing=true;render();break;case'share-return':model.systemSharing=false;scenario='文件已准备';render();break;case'noop':break;case'close':close();break;case'back':remember();route=stack.pop()||tab;scenario=info(route).states[0];render();break;case'library-all':model.kind='all';scenario='正常';render();break;case'photos-allow':modal=null;modalStack=[];route='library';scenario='正常';notify(T('模拟授权完成，只显示演示照片。','Simulated access granted; only demo photos are shown.'));break;case'picker-picked':selected.clear();selected.add(0);selected.add(1);modal='selected-backup';scenario='正常';render();break;case'picker-cancel':close();break;case'confirm-backup':simulateSaving(()=>{selected.clear();modal=null;modalStack=[];route='backup';tab='backup';scenario='正常'});break;case'pause':scenario='手动暂停';notify(T('当前传输已暂停；新增自动备份配置不改变。','Current transfers paused; the automatic-backup setting is unchanged.'));break;case'resume':scenario='传输中';notify(T('已请求继续传输。','Resume requested.'));break;case'pair-validate':scenario='校验中';busy=true;render();setTimeout(()=>{busy=false;scenario='配对成功';model.paired=true;render()},420);break;case'pair-done':model.paired=true;close();break;case'scan-again':scenario='扫描中';model.error='';render();break;case'camera-allow':modal='pair-scan';modalStack=[];scenario='扫描中';render();break;case'camera-deny':modal='pair-scan';modalStack=[];scenario='相机权限被拒绝';render();break;case'system-return':close();break;case'system-failed':scenario='打开失败';render();break;case'check-connection':scenario='检查中';render();setTimeout(()=>{scenario='已配对';notify(T('演示连接检查完成；不代表云端结果。','Demo connection check completed; this does not confirm cloud upload.'))},400);break;case'retry':scenario='正常';notify(T('已重新读取演示数据。','Demo data reloaded.'));break;case'retry-detail':scenario='重试中';busy=true;render();setTimeout(()=>{busy=false;scenario='已接收待处理';notify(T('重试请求已提交，不表示处理成功。','Retry submitted; processing success is not yet confirmed.'))},360);break;case'load-more':model.page++;notify(T(`已加载 ${model.page*200} 项（演示），列表不跳回顶部。`,`Loaded ${model.page*200} items (demo); scroll position is retained.`));break;case'history-start':case'history-resume':model.history='扫描中';scenario='扫描中';notify(T('开始检查已有照片快照，不改变新增备份开关。','Scanning the existing-photo snapshot; the new-item setting is unchanged.'));break;case'history-pause':model.history='已暂停';scenario='已暂停';notify(T('历史扫描已暂停。','Historical scanning paused.'));break;case'reclaim':scenario='检查中';render();setTimeout(()=>{scenario='回收完成';render()},400);break;case'logs-latest':model.pendingLogs=0;scenario='正常';notify(T('已定位到最新记录。','Moved to the latest records.'));break;case'recommended':ordering.delete(model.filter);close();break;case'save-name':{const name=model.draftName.trim();const count=[...name].length;if(!count||count>40||/[\u0000-\u001F\u007F-\u009F\u202A-\u202E\u2066-\u2069]/u.test(name)){model.error=L('device_name_invalid');focusAfterRender='[data-name]';render();break}simulateSaving(()=>{model.name=name;close()});break}default:throw new Error('Unhandled prototype action: '+action)}}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el||el.disabled)return;if(el.dataset.tab){navigate(el.dataset.tab,true);return}if(el.dataset.catalog){const id=el.dataset.catalog,entry=info(id);const owner=entry.path.startsWith('图库')?'library':entry.path.startsWith('备份')?'backup':entry.path.startsWith('接收设备')?'receiver':'settings';navigate(owner,true);if(id!==owner)present(id);return}if(el.dataset.open){present(el.dataset.open);if(el.dataset.openingScene){scenario=el.dataset.openingScene;render()}return}if(el.dataset.action){act(el.dataset.action);return}if(el.dataset.photo!==undefined){const id=+el.dataset.photo;if(libraryPressConsumed!==undefined&&libraryPressConsumed!==null){return;}remember();if(model.selecting){selected.has(id)?selected.delete(id):selected.add(id);render()}else{model.preview=id;present('photo-preview')}return}if(el.dataset.file!==undefined){model.file=+el.dataset.file;if(el.dataset.source){notify(T('这是来源准备记录，尚未形成传输任务。','This is an original-preparation record, not a transfer job.'));return}present('transfer-detail');return}if(el.dataset.filter){model.filter=el.dataset.filter;render();return}if(el.dataset.choice){const key=el.dataset.choice,val=el.dataset.value;if(key==='sort'||key==='order'){let current=ordering.get(model.filter)||{basis:'capture',desc:true};if(key==='sort')current.basis=val;else current.desc=val==='desc';ordering.set(model.filter,current);render()}else if(['kind','filter'].includes(key)){model[key]=val;close();}else simulateSaving(()=>{model[key]=['cache','minFree','days','limit','concurrency'].includes(key)?+val:val;if(key==='appearance'){$('#dark').checked=val==='dark';document.body.classList.toggle('dark',val==='dark')}close()})}});
document.addEventListener('input',e=>{if(e.target.matches('[data-name]')){model.draftName=e.target.value;model.error='';const save=$('[data-action="save-name"]');if(save)save.disabled=busy||!model.draftName.trim()}});
document.addEventListener('change',e=>{if(e.target.dataset.toggle){const key=e.target.dataset.toggle,desired=e.target.checked;if(key==='rebackup'){model[key]=desired;render()}else simulateSaving(()=>model[key]=desired)}});
$('#search').addEventListener('input',render);$('#scenario').addEventListener('change',e=>{scenario=e.target.value;model.error='';model.failedOnce=false;model.systemSharing=false;const active=modal||route;if(active==='library')model.selecting=scenario==='多选';busy=['device-name','selected-backup','pair-scan','diagnostic-share'].includes(active)&&/保存中|提交中|校验中|重试中/.test(scenario);if(active==='transfer-sort'){const filterByState={'已接收':'received','失败':'failed','准备原件':'preparing','历史扫描':'scanned'};if(filterByState[scenario])model.filter=filterByState[scenario]}feedback='';if((modal||route)==='device-name'){model.draftName=scenario==='空白'?'':scenario==='长度超过40'?'A'.repeat(41):scenario==='非法字符'?'Name\u202E':model.name}render()});$('#locale').addEventListener('change',e=>{locale=e.target.value;render()});$('#width').addEventListener('change',e=>{const w=+e.target.value;$('#device').style.width=w+'px';$('#device').style.height=w===768?'980px':'844px';$('#device').classList.toggle('ipad',w===768)});$('#font').addEventListener('change',e=>{$('#device').style.setProperty('--font',e.target.value);$('#device').classList.toggle('large-font',+e.target.value>=1.4)});$('#dark').addEventListener('change',e=>document.body.classList.toggle('dark',e.target.checked));$('#solid').addEventListener('change',e=>document.body.classList.toggle('solid',e.target.checked));$('#motion').addEventListener('change',e=>document.body.classList.toggle('reduce-motion',e.target.checked));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal)close()});
const initial=new URLSearchParams(location.search).get('screen');if(initial&&info(initial)){tab=info(initial).path.startsWith('图库 →')||initial==='library'?'library':info(initial).path.startsWith('备份 →')||initial==='backup'?'backup':['receiver','receiver-status','pair-scan','system-camera'].includes(initial)?'receiver':'settings';if(!['page','inline','reading'].includes(info(initial).kind))route=tab;if(['page','inline','reading'].includes(info(initial).kind)){route=initial;if(!nav.some(n=>n[0]===initial))stack=initial.startsWith('help-')?[tab,'help']:[tab];}else modal=initial;scenario=info(initial).states[0]}render();

// Scoped feedback actions; do not alter the library/selected-backup state machine.
document.addEventListener('click',e=>{const sort=e.target.closest('[data-sort-result]');if(sort){const [basis,direction]=sort.dataset.sortResult.split('_');ordering.set(model.filter,{basis,desc:direction==='latest'});close();return}const log=e.target.closest('[data-log-entry]');if(log){model.logEntry=+log.dataset.logEntry;present('activity-detail')}});


// Review-only deterministic selection range. Never reads PhotoKit or user files.
class GalleryRangeSession {
  constructor(ids,base,anchor) { this.ids=[...ids];this.base=new Set(base);this.anchor=anchor;this.end=anchor;this.add=!this.base.has(this.ids[anchor]); }
  apply(end) {this.end=end;const output=new Set(this.base);for(let i=Math.min(this.anchor,end);i<=Math.max(this.anchor,end);i++){this.add?output.add(this.ids[i]):output.delete(this.ids[i])}return output}
}
let libraryPressTimer, libraryPressPoint, libraryPressConsumed, libraryDrag, libraryAutoFrame;
function replaceSelection(set){selected.clear();for(const id of set)selected.add(id)}
function refreshSelectionChrome(){
 for(const cell of document.querySelectorAll('[data-photo]')){const id=Number(cell.dataset.photo),chosen=selected.has(id);cell.classList.toggle('selected',chosen);cell.setAttribute('aria-pressed',String(chosen));const mark=cell.querySelector('.selection');if(mark)mark.innerHTML=chosen?icon('check'):''}
 const title=$('[data-library-title]');if(title&&model.selecting)title.textContent=T(`已选 ${selected.size} 项`,`${selected.size} selected`);
 const backup=$('.compact-backup');if(backup)backup.disabled=!selected.size||!model.paired;
}
function rangeHit(){if(!libraryDrag||!libraryPressPoint)return;const c=$('.content'),r=c.getBoundingClientRect(),y=Math.max(r.top+1,Math.min(r.bottom-1,libraryPressPoint.y));const cell=document.elementFromPoint(libraryPressPoint.x,y)?.closest('[data-photo]');if(!cell)return;const index=libraryDrag.ids.indexOf(Number(cell.dataset.photo));if(index<0)return;replaceSelection(libraryDrag.apply(index));refreshSelectionChrome()}
function rangeAutoScroll(){if(!libraryDrag||!libraryPressPoint)return;const c=$('.content'),r=c.getBoundingClientRect(),y=libraryPressPoint.y;const delta=y<r.top+44?-Math.min(12,(r.top+44-y)/3):y>r.bottom-44?Math.min(12,(y-r.bottom+44)/3):0;if(delta){c.scrollTop=Math.max(0,Math.min(c.scrollHeight-c.clientHeight,c.scrollTop+delta));offsets.set(route,c.scrollTop);rangeHit()}libraryAutoFrame=requestAnimationFrame(rangeAutoScroll)}
function endRange(cancelled){clearTimeout(libraryPressTimer);cancelAnimationFrame(libraryAutoFrame);if(cancelled&&libraryDrag){replaceSelection(libraryDrag.base);model.selecting=libraryDrag.wasSelecting;render()}libraryDrag=null;libraryPressPoint=null;setTimeout(()=>libraryPressConsumed=null,0)}
document.addEventListener('pointerdown',e=>{const cell=e.target.closest('[data-photo]');if(!cell||modal)return;const id=Number(cell.dataset.photo);libraryPressPoint={x:e.clientX,y:e.clientY,originY:e.clientY};libraryPressTimer=setTimeout(()=>{remember();const ids=demoFiles.filter(f=>model.kind==='all'||f.kind===model.kind).map(f=>f.id),anchor=ids.indexOf(id);if(anchor<0)return;libraryDrag=new GalleryRangeSession(ids,selected,anchor);libraryDrag.wasSelecting=model.selecting;replaceSelection(libraryDrag.apply(anchor));model.selecting=true;libraryPressConsumed=id;render();rangeAutoScroll()},400)});
document.addEventListener('pointermove',e=>{if(!libraryPressPoint)return;if(libraryDrag){libraryPressPoint.x=e.clientX;libraryPressPoint.y=e.clientY;e.preventDefault();rangeHit();return}const moved=Math.hypot(e.clientX-libraryPressPoint.x,e.clientY-libraryPressPoint.y);if(moved>8){clearTimeout(libraryPressTimer);const c=$('.content');c.scrollTop+=libraryPressPoint.y-e.clientY;libraryPressPoint.x=e.clientX;libraryPressPoint.y=e.clientY;offsets.set(route,c.scrollTop)}},{passive:false});
document.addEventListener('pointerup',()=>endRange(false));document.addEventListener('pointercancel',()=>endRange(true));
window.galleryReview={setBrowse(){endRange(false);model.selecting=false;selected.clear();route='library';modal=null;scenario='正常';render()},setSelection(ids){endRange(false);replaceSelection(new Set(ids));model.selecting=true;route='library';modal=null;scenario='正常';render()},inspect:()=>({selected:[...selected],selecting:model.selecting,drag:libraryDrag?{anchor:libraryDrag.anchor,end:libraryDrag.end,add:libraryDrag.add}:null}),range:(ids,base,anchor,end)=>[...new GalleryRangeSession(ids,base,anchor).apply(end)]};
